import SwiftUI

/// Named vector layers shared with Design/RescueFriends. Gentle motion uses the ocean clock.
enum RescueArt {
    enum Asset:String {case shellSeat,pearlLantern,interior,enterHome,leaveHome,homeShop,homeFurniture,roomOverview,roomWindow}
    struct Layer {let name:String;let path:Path;let fill:UInt32?;let stroke:UInt32?;let width:Double}
    static func draw(_ asset:Asset,in context:GraphicsContext,at point:CGPoint,size:Double,time:Double=0,moving:Bool=true,facing:Double=1) {
        var c=context;c.translateBy(x:point.x,y:point.y);c.scaleBy(x:size/300*facing,y:size/300);c.translateBy(x:-150,y:-150)
        for p in layers[asset] ?? [] {
            var part=c
            if moving && (p.name.hasPrefix("tail") || p.name.hasPrefix("fin") || p.name.contains("flipper")) {
                let anchor=CGPoint(x:165,y:155)
                let angle=sin(time/2400 * .pi*2)*(p.name.contains("flipper") ? 7:5)
                part.translateBy(x:anchor.x,y:anchor.y);part.rotate(by:.degrees(angle));part.translateBy(x:-anchor.x,y:-anchor.y)
            }
            if let fill=p.fill {part.fill(p.path,with:.color(Color(hex:fill)))}
            if let stroke=p.stroke {part.stroke(p.path,with:.color(Color(hex:stroke)),style:.init(lineWidth:p.width,lineCap:.round,lineJoin:.round))}
        }
    }
    private static let layers:[Asset:[Layer]] = [
